constraints:
1 <= N <= 10^{5}
1 <= A[i] <= 10^{9}

expected time complexity: O(N)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def numberOfSubsequences(ob, N, A):
		count = 0
		for item in A:
			count += bin(item).count('1') == 1
		return (2 ** count - 1) % (10 ** 9 + 7)
